//! The `Report` Mapping attribute: `tran1` and `tran2` write the effect of
//! each transformation to the thread's report writer, as C's `astTran1` and
//! `astTran2` print it (mapping.c `ReportPoints` and the FrameSet and Region
//! versions), and `Report` is dumped and read back as C does.
//!
//! `report_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/report_probe.c`.

use crate::common::native_dump;
// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "report_oracle/cases.rs"]
mod cases;

use std::cell::RefCell;
use std::io::Write;
use std::rc::Rc;

use starlink_ast::constants::BAD_VALUE;
use starlink_ast::frames::{BasicFrameBuilder, FrameRef, FrameSet, SkyFrame};
use starlink_ast::mappings::report::{reset_report_sink, set_report_sink};
use starlink_ast::mappings::{Mapping, ShiftMap, ZoomMap};
use starlink_ast::regions::CircleBuilder;
use starlink_ast::{AnyObject, from_native_string};

/// A report writer that collects what is written.
#[derive(Clone, Default)]
struct Captured(Rc<RefCell<Vec<u8>>>);

impl Write for Captured {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        self.0.borrow_mut().extend_from_slice(buf);
        Ok(buf.len())
    }
    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

/// What `f` reports.
fn report_of(f: impl FnOnce()) -> String {
    let captured = Captured::default();
    set_report_sink(Box::new(captured.clone()));
    f();
    reset_report_sink();
    String::from_utf8(captured.0.borrow().clone()).unwrap()
}

fn xs() -> Vec<f64> {
    cases::X.iter().map(|x| x.unwrap_or(BAD_VALUE)).collect()
}

fn plain2() -> starlink_ast::frames::BasicFrame {
    BasicFrameBuilder::new(2).build().unwrap()
}

fn text(lines: &[&str]) -> String {
    let mut s = lines.join("\n");
    s.push('\n');
    s
}

#[test]
fn reports_follow_the_c_library() {
    let (x, y) = (xs(), cases::Y.to_vec());

    let mut zoom = ZoomMap::new(2, 2.5).unwrap();
    zoom.set_report(true);
    let got = report_of(|| {
        zoom.tran2(&x, &y, true).unwrap();
        zoom.tran2(&x, &y, false).unwrap();
    });
    assert_eq!(got, cases::ZOOM, "ZoomMap");

    let mut shift = ShiftMap::new(vec![1.25]);
    shift.set_report(true);
    let got = report_of(|| {
        shift.tran1(&x, true).unwrap();
    });
    assert_eq!(got, cases::SHIFT, "ShiftMap");

    let mut fs = FrameSet::new(Box::new(plain2()));
    fs.set_report(true);
    fs.add_frame(
        FrameRef::Base,
        Box::new(ZoomMap::new(2, 0.01).unwrap()),
        Box::new(SkyFrame::unset_system()),
    )
    .unwrap();
    let got = report_of(|| {
        fs.tran2(&x, &y, true).unwrap();
        fs.tran2(&x, &y, false).unwrap();
    });
    assert_eq!(got, cases::FRAMESET, "FrameSet");

    let mut circle = CircleBuilder::new(plain2(), vec![0.0, 0.0])
        .unwrap()
        .radius(2.0)
        .build()
        .unwrap();
    circle.set_report(true);
    let got = report_of(|| {
        circle.tran2(&x, &y, true).unwrap();
    });
    assert_eq!(got, cases::CIRCLE, "Circle");

    // Without Report, nothing is written.
    zoom.clear_report();
    assert_eq!(report_of(|| drop(zoom.tran2(&x, &y, true))), "");
    zoom.set_report(true);

    let mut failures = Vec::new();
    let mut zoom_off = zoom.clone();
    zoom_off.set_report(false);
    for (name, obj, want) in [
        ("ZoomMap", AnyObject::ZoomMap(zoom), cases::ZOOM_DUMP),
        (
            "ZoomMap Report=0",
            AnyObject::ZoomMap(zoom_off),
            cases::ZOOM_DUMP_OFF,
        ),
        ("FrameSet", AnyObject::FrameSet(fs), cases::FRAMESET_DUMP),
        ("Circle", AnyObject::Circle(circle), cases::CIRCLE_DUMP),
    ] {
        let written = native_dump(&obj).unwrap();
        if written != text(want) {
            failures.push(format!(
                "{name}: dump differs\n{written}\nC:\n{}",
                text(want)
            ));
        }
        // The dump reads back with Report as C wrote it.
        let back = from_native_string(&text(want)).unwrap();
        let m = back.as_mapping().expect("a Mapping");
        let want_report = want
            .iter()
            .any(|l| l.trim_start().starts_with("Report = 1"));
        if (m.test_report(), m.report()) != (true, want_report) {
            failures.push(format!("{name}: Report reads back as {}", m.report()));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// A copy clears Report, as C's `astCopy` does for a Mapping, a FrameSet and
/// a Region alike.
#[test]
fn a_clone_clears_report() {
    let mut zoom = ZoomMap::new(3, 2.0).unwrap();
    zoom.set_report(true);
    let copy = zoom.clone();
    assert!(!copy.test_report());
    assert!(zoom.test_report() && zoom.report());

    let mut fs = FrameSet::new(Box::new(plain2()));
    fs.set_report(true);
    assert!(!fs.clone().test_report());

    let mut circle = CircleBuilder::new(plain2(), vec![0.0, 0.0])
        .unwrap()
        .radius(1.0)
        .build()
        .unwrap();
    circle.set_report(true);
    assert!(!circle.clone().test_report());
    assert!(!starlink_ast::regions::Region::clone_region(&circle).test_report());
}

/// Wrapping a Mapping held as a trait object to write it is not a copy, so
/// the dump records Report as C's `astWrite` does.
#[test]
fn a_dump_through_from_mapping_keeps_report() {
    let mut zoom = ZoomMap::new(2, 2.5).unwrap();
    zoom.set_report(true);
    let m: &dyn Mapping = &zoom;
    let written = native_dump(&AnyObject::from_mapping(m).unwrap()).unwrap();
    assert_eq!(written, text(cases::ZOOM_DUMP));
}
